import re
from robot.api import logger

from ta_egate_cmd_parser.egate_output_parser_base import EgateDispCommandsOutputParser
from ta_egate_cmd_parser.egate_command_base import EgateCommandBase
from ta_egate_cmd_parser.utils.converters import create_dict_with_key


class ProxyLogFailure(Exception):
    """
    Exception class for proxy_log
    """
    pass


class ProxyLog(EgateCommandBase):
    """
    Parser for proxy_log command output.
    """

    def __init__(self, **params):
        """

        :param params:
        """
        super(ProxyLog, self).__init__()
        self.command = 'proxy_log'
        self.params = params
        self.executed_phrase = r'.*?eNB\-\d+\s+cell\-\d+.*?EGATE>'
        self.fail_regexp = 'Error:'
        self.to_execute = self.command
        self._build_command()
        logger.debug('{}: {} command to execute:\n{}'.format(self.__class__.__name__, self.command, self.to_execute))

    def execute(self, egate_id=0):
        """
        Execute proxy_log command.
        :return: command status and output
        """
        status, output = super(ProxyLog, self).execute(egate_id=egate_id, command=self.to_execute, fail_regexp=self.fail_regexp)
        if status:
            return status, output
        else:
            raise ProxyLogFailure(output)

    def execute_and_parse(self, egate_id=0):
        """

        :return:
        """
        status, output = super(ProxyLog, self).execute(egate_id=egate_id, command=self.to_execute)
        if status:
            parsed_output = self._parse_proxy_log_output(output)
            logger.debug('{}: {} cmd parsed output:\n{}'.format(self.__class__.__name__, self.command, parsed_output))
            return parsed_output
        else:
            raise ProxyLogFailure(output)

    def _build_command(self):
        """
        Build proxy_log command.
        :return: None
        """
        for param, value in self.params.items():
            self.to_execute += ' {}={}'.format(param, value)

    def _parse_proxy_log_output(self, output):
        """

        :param output:
        :return:
        """
        if {'cell', 'enb'}.issubset(set(list(self.params.keys()))):
            return self._parse_with_enb_and_cell_id(output)
        elif 'cell' in list(self.params.keys()):
            return self._parse_with_enb_and_cell_id(output)
        elif 'enb' in list(self.params.keys()):
            return self._parse_with_enb_id(output)
        else:
            return self._parse_without_id(output)

    def _parse_with_enb_and_cell_id(self, cmd_output):
        """

        :param cmd_output:
        :return:
        """
        cell_regexp = r'(eNB\-\d+\s+)(cell\-\d+)([\s\S]*?)(?=\sbitmap)(.*bitmap\s\=*)([\s\S]*?)(?=\=)'
        cell_table = re.search(cell_regexp, cmd_output)

        cmd_parser = EgateDispCommandsOutputParser(cell_table.group(3))
        output = cmd_parser.get_list_of_output_parsed_lines()
        logs_level_config = create_dict_with_key(key='Feature', list_of_output_parsed_lines=output)
        logs_level_config['bitmap'] = cell_table.group(5).lstrip().rstrip()

        return logs_level_config

    def _parse_with_enb_id(self, cmd_output):
        """

        :param cmd_output:
        :return:
        """
        cell_regexp = r'(eNB\-\d+\s+)(cell\-\d+)([\s\S]*?)(?=\sbitmap)(.*bitmap\s\=*)([\s\S]*?)(?=\=)'
        cells_table = re.findall(cell_regexp, cmd_output)

        logs_level_config = dict()

        for cell in cells_table:
            cell_id = cell[1].split('-')[1]
            cell_logs_level_table = cell[2]
            cell_bitmap = cell[4].lstrip().rstrip()

            cell_log_level_config = self._parse_cell_log_level_config(cell_logs_level_table)
            logs_level_config[cell_id] = cell_log_level_config
            logs_level_config[cell_id]['bitmap'] = cell_bitmap

        return logs_level_config

    def _parse_without_id(self, cmd_output):
        """

        :param cmd_output:
        :return:
        """
        cell_regexp = r'(eNB\-\d+\s+)(cell\-\d+)([\s\S]*?)(?=\sbitmap)(.*bitmap\s\=*)([\s\S]*?)(?=\=)'
        cells_table = re.findall(cell_regexp, cmd_output)

        logs_level_config = dict()

        for cell in cells_table:
            enb_id = cell[0].split('-')[1]
            cell_id = cell[1].split('-')[1]
            cell_logs_level_table = cell[2]
            cell_bitmap = cell[4].lstrip().rstrip()

            cell_log_level_config = self._parse_cell_log_level_config(cell_logs_level_table)
            if enb_id not in list(logs_level_config.keys()):
                logs_level_config[enb_id] = dict()
                logs_level_config[enb_id][cell_id] = cell_log_level_config
                logs_level_config[enb_id][cell_id]['bitmap'] = cell_bitmap
            else:
                logs_level_config[enb_id][cell_id] = cell_log_level_config
                logs_level_config[enb_id][cell_id]['bitmap'] = cell_bitmap

        return logs_level_config

    def _parse_cell_log_level_config(self, logs_level_table):
        cmd_parser = EgateDispCommandsOutputParser(logs_level_table)
        output = cmd_parser.get_list_of_output_parsed_lines()
        return create_dict_with_key(key='Feature', list_of_output_parsed_lines=output)
